// =============================================================
// HERMES WEEKLY PERFORMANCE SUMMARY (Last 7 Days — Football vs NBA)
// Reads HermesPicks Google Sheet, deduplicates, computes ROI & Bankroll Growth!
// =============================================================
const rows = $input.all();
const now = new Date();
const sevenDaysAgoMs = now.getTime() - 7 * 24 * 60 * 60 * 1000;
const BANKROLL_TZS = parseInt($env.HERMES_BANKROLL_TZS || '100000', 10);
const UNIT_TZS = Math.round(BANKROLL_TZS / 100);

function esc(t) {
  return String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const weekDedup = {};
const allTimeDedup = {};

for (const r of rows) {
  const row = r.json || {};
  if (!row.Match) continue;
  const res = String(row.Result || '').trim().toUpperCase();
  if (res !== 'WIN' && res !== 'LOSS') continue;

  const tsStr = String(row.KickoffISO || row.Timestamp || '').trim();
  const dt = tsStr ? new Date(tsStr) : now;
  const validMs = !isNaN(dt.getTime()) ? dt.getTime() : now.getTime();
  const dateKey = new Date(validMs).toLocaleDateString('en-CA', { timeZone: 'Africa/Dar_es_Salaam' });

  const league = String(row.League || '');
  const market = String(row.Market || '');
  const isBasket = /nba|ncaa|basket|🏀/i.test(league) || /pts|spread|\sml\s/i.test(market);
  const conf = String(row.Confidence || '');
  const isRisky = conf.includes('RISKY') || conf.includes('🔴');

  const odds = parseFloat(row.Odds) || 0;
  const units = parseFloat(row.StakeUnits) || 0;
  const payout = res === 'WIN' ? +(units * odds).toFixed(2) : 0;
  const profit = +(payout - units).toFixed(2);
  const roi = units > 0 ? +((profit / units) * 100).toFixed(1) : 0;

  const dk = dateKey + '::' + String(row.Match).toLowerCase() + '::' + market.toLowerCase();
  const obj = { dateKey, match: row.Match, league, market, odds, units, payout, profit, roi, result: res, isBasket, isRisky };

  allTimeDedup[dk] = obj;
  if (validMs >= sevenDaysAgoMs) {
    weekDedup[dk] = obj;
  }
}

const weekAll = Object.values(weekDedup);
const weekSafe = weekAll.filter(x => !x.isRisky);
const weekFb = weekSafe.filter(x => !x.isBasket);
const weekBb = weekSafe.filter(x => x.isBasket);
const allTimeSafe = Object.values(allTimeDedup).filter(x => !x.isRisky);

function stats(arr) {
  const w = arr.filter(x => x.result === 'WIN').length;
  const l = arr.length - w;
  const st = arr.reduce((a, b) => a + b.units, 0);
  const ret = arr.reduce((a, b) => a + b.payout, 0);
  const pr = ret - st;
  const roi = st > 0 ? (pr / st) * 100 : 0;
  const wr = arr.length > 0 ? (w / arr.length) * 100 : 0;
  const tzs = Math.round(pr * UNIT_TZS);
  return { n: arr.length, w, l, st, ret, pr, roi, wr, tzs };
}

const sWeek = stats(weekSafe);
const sFb = stats(weekFb);
const sBb = stats(weekBb);
const sAllTime = stats(allTimeSafe);

const ds = now.toLocaleDateString('sw-TZ', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Africa/Dar_es_Salaam' });
const startDs = new Date(sevenDaysAgoMs).toLocaleDateString('sw-TZ', { day: 'numeric', month: 'short', timeZone: 'Africa/Dar_es_Salaam' });

function bar(wr) {
  const filled = Math.round(wr / 10);
  return '🟩'.repeat(Math.max(0, Math.min(10, filled))) + '⬜'.repeat(Math.max(0, 10 - filled));
}

let msg = '📈 HERMES WEEKLY PERFORMANCE REPORT (7 DAYS)\n';
msg += '📅 Kipindi: ' + startDs + ' – ' + ds + '\n';
msg += '⚡ Google Sheet Ledger (🟢 STRONG &amp; 🟡 MODERATE Pekee)\n';
msg += '━━━━━━━━━━━━━━━━━━━━━━\n\n';

if (sWeek.n === 0) {
  msg += '📭 Hakuna mechi za 🟢/🟡 zilizosahihishwa wiki hii bado.\n';
} else {
  const curBankroll = BANKROLL_TZS + sAllTime.tzs;
  const growthPct = ((sAllTime.tzs / BANKROLL_TZS) * 100).toFixed(1);

  msg += '🏆 MATOKEO YA WIKI (PESA HALISI):\n';
  msg += '• Jumla: ' + sWeek.w + 'W / ' + sWeek.l + 'L (' + sWeek.wr.toFixed(1) + '% Win Rate)\n';
  msg += '  ' + bar(sWeek.wr) + '\n';
  msg += '• Units: ' + (sWeek.pr >= 0 ? '+' : '') + sWeek.pr.toFixed(2) + 'u (' + (sWeek.roi >= 0 ? '+' : '') + sWeek.roi.toFixed(1) + '% ROI) ' + (sWeek.pr >= 0 ? '🟢' : '🔴') + '\n';
  msg += '• Faida Wiki Hii: ' + (sWeek.tzs >= 0 ? '+TZS ' : '-TZS ') + Math.abs(sWeek.tzs).toLocaleString() + '\n\n';

  msg += '⚽ FOOTBALL WIKI HII:\n';
  msg += '• ' + sFb.w + 'W / ' + sFb.l + 'L (' + sFb.wr.toFixed(1) + '% WR) | ' + (sFb.pr >= 0 ? '+' : '') + sFb.pr.toFixed(2) + 'u (' + (sFb.roi >= 0 ? '+' : '') + sFb.roi.toFixed(1) + '% ROI)\n';
  msg += '• Pochi ya Football: ' + (sFb.tzs >= 0 ? '+TZS ' : '-TZS ') + Math.abs(sFb.tzs).toLocaleString() + '\n\n';

  msg += '🏀 NBA BASKETBALL WIKI HII:\n';
  msg += '• ' + sBb.w + 'W / ' + sBb.l + 'L (' + sBb.wr.toFixed(1) + '% WR) | ' + (sBb.pr >= 0 ? '+' : '') + sBb.pr.toFixed(2) + 'u (' + (sBb.roi >= 0 ? '+' : '') + sBb.roi.toFixed(1) + '% ROI)\n';
  msg += '• Pochi ya Basketball: ' + (sBb.tzs >= 0 ? '+TZS ' : '-TZS ') + Math.abs(sBb.tzs).toLocaleString() + '\n\n';

  const winsSorted = weekSafe.filter(x => x.result === 'WIN').sort((a, b) => b.profit - a.profit);
  const lossSorted = weekSafe.filter(x => x.result === 'LOSS').sort((a, b) => a.profit - b.profit);
  if (winsSorted.length > 0) {
    const mvp = winsSorted[0];
    msg += '🌟 MVP PICK YA WIKI: ' + esc(mvp.match) + ' → ' + esc(mvp.market) + ' @ ' + mvp.odds.toFixed(2) + ' (+' + mvp.profit.toFixed(2) + 'u) 🔥\n';
  }
  if (lossSorted.length > 0) {
    const worst = lossSorted[0];
    msg += '⚠️ SOMO LA WIKI: ' + esc(worst.match) + ' → ' + esc(worst.market) + ' (' + worst.profit.toFixed(2) + 'u)\n';
  }

  msg += '\n━━━━━━━━━━━━━━━━━━━━━━\n';
  msg += '💰 MWENENDO WA MTAJI (BANKROLL GROWTH):\n';
  msg += '• Mtaji wa Kuanzia: TZS ' + BANKROLL_TZS.toLocaleString() + '\n';
  msg += '• Mtaji wa Sasa: TZS ' + curBankroll.toLocaleString() + ' (' + (sAllTime.tzs >= 0 ? '+' : '') + growthPct + '%) ' + (sAllTime.tzs >= 0 ? '📈' : '📉') + '\n';

  const leader = sFb.roi >= sBb.roi ? '⚽ Football' : '🏀 NBA Basketball';
  msg += '💡 MWELEKEO WA WIKI IJAYO: ' + leader + ' imeongoza kwa ROI wiki hii — endelea kuweka 40/40/20 kupitia BetPawa Slip Helper!\n';
}

msg += '\n🤖 mwijay.duckdns.org · Weekly Performance Engine';
return [{ json: { weeklyText: msg } }];
